<?php
require_once '../config/app.php'; require_once '../includes/security.php'; start_secure_session(); require_permission('applications.manage'); $pdo=db(); $error=null;
if($_SERVER['REQUEST_METHOD']==='POST') {
 if(!csrf_check($_POST['_csrf']??'')) $error='Invalid request.';
 else try {
  $action=$_POST['action']??'';
  if($action==='create') {
   $job=(int)$_POST['job_id']; $name=trim($_POST['template_name']);
   $pdo->prepare("INSERT INTO application_templates(job_id,template_name,official_form_url,instructions,status,created_by) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE template_name=VALUES(template_name),official_form_url=VALUES(official_form_url),instructions=VALUES(instructions),updated_at=NOW()")
    ->execute([$job,$name,trim($_POST['official_form_url']),trim($_POST['instructions']),$_POST['status']==='active'?'active':'draft',$_SESSION['admin_id']]);
   flash('success','Application template saved.'); redirect('application-templates.php?job='.$job);
  }
  if($action==='field') {
   $tid=(int)$_POST['template_id']; $key=preg_replace('/[^a-zA-Z0-9_]/','_',trim($_POST['field_key']));
   if($key==='') throw new Exception('Invalid field key');
   $opts=trim($_POST['options_json']); if($opts!==''){json_decode($opts,true); if(json_last_error()!==JSON_ERROR_NONE) throw new Exception('Options must be valid JSON');}
   $pdo->prepare("INSERT INTO application_template_fields(template_id,field_key,field_label,input_type,profile_source,required,options_json,help_text,sort_order) VALUES(?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE field_label=VALUES(field_label),input_type=VALUES(input_type),profile_source=VALUES(profile_source),required=VALUES(required),options_json=VALUES(options_json),help_text=VALUES(help_text),sort_order=VALUES(sort_order)")
    ->execute([$tid,$key,trim($_POST['field_label']),$_POST['input_type'],trim($_POST['profile_source']),isset($_POST['required'])?1:0,$opts?:null,trim($_POST['help_text']),(int)$_POST['sort_order']]);
   flash('success','Application field saved.'); redirect('application-templates.php?template='.$tid);
  }
  if($action==='delete_field') {$id=(int)$_POST['id']; $pdo->prepare('DELETE FROM application_template_fields WHERE id=?')->execute([$id]); flash('success','Field removed.'); redirect('application-templates.php?template='.(int)$_POST['template_id']);}
  if($action==='status') {$tid=(int)$_POST['template_id']; $s=in_array($_POST['status'],['draft','active','archived'],true)?$_POST['status']:'draft'; $pdo->prepare('UPDATE application_templates SET status=? WHERE id=?')->execute([$s,$tid]); flash('success','Template status updated.'); redirect('application-templates.php?template='.$tid);}
 } catch(Throwable $e){$error='Could not save the application template. Check the values and run sql/v8-migration.sql first.';}
}
$jobs=$pdo->query("SELECT id,job_uid,job_title,organization,status,application_url FROM jobs ORDER BY created_at DESC")->fetchAll();
$tid=(int)($_GET['template']??0); $jobid=(int)($_GET['job']??0); $template=null; $fields=[];
if($tid){$st=$pdo->prepare('SELECT t.*,j.job_title,j.organization FROM application_templates t JOIN jobs j ON j.id=t.job_id WHERE t.id=?');$st->execute([$tid]);$template=$st->fetch();}
if(!$template && $jobid){$st=$pdo->prepare('SELECT t.*,j.job_title,j.organization FROM application_templates t JOIN jobs j ON j.id=t.job_id WHERE t.job_id=?');$st->execute([$jobid]);$template=$st->fetch();}
if($template){$tid=(int)$template['id'];$st=$pdo->prepare('SELECT * FROM application_template_fields WHERE template_id=? ORDER BY sort_order,id');$st->execute([$tid]);$fields=$st->fetchAll();}
$page_title='Application Templates';$asset_prefix='../';$home_link='../index.php';require '../includes/header.php';
?>
<div class="page-head"><div><span class="eyebrow">APPLICATION ASSISTANCE</span><h1>Application Templates</h1><p class="muted">Map candidate master-profile data to a recruitment form. This assists the candidate; it does not bypass CAPTCHA, OTP or official submission/payment.</p></div></div>
<?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?>
<div class="card"><h2>Create / Update Template</h2><form class="form-grid" method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create"><label>Job*<select name="job_id" required><option value="">Select job</option><?php foreach($jobs as $j):?><option value="<?=$j['id']?>" <?=($template&&$template['job_id']==$j['id'])?'selected':''?>><?=e($j['job_title'].' — '.$j['organization'].' ['.$j['status'].']')?></option><?php endforeach;?></select></label><label>Template Name*<input name="template_name" required value="<?=e($template['template_name']??'') ?>"></label><label>Official Form URL<input name="official_form_url" type="url" value="<?=e($template['official_form_url']??'') ?>"></label><label>Status<select name="status"><option value="draft">Draft</option><option value="active" <?=($template['status']??'')==='active'?'selected':''?>>Active</option></select></label><label style="grid-column:1/-1">Instructions<textarea name="instructions" rows="3"><?=e($template['instructions']??'')?></textarea></label><div class="form-actions"><button class="btn btn-primary">Save Template</button></div></form></div>
<?php if($template):?><div class="card"><h2><?=e($template['template_name'])?></h2><p class="muted"><?=e($template['job_title'])?> · <?=e($template['organization'])?> · Status: <b><?=e($template['status'])?></b></p><form method="post" style="margin-bottom:16px"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="template_id" value="<?=$tid?>"><select name="status"><option value="draft">Draft</option><option value="active">Active</option><option value="archived">Archived</option></select> <button class="btn btn-light">Update Status</button></form><h3>Add / Update Field</h3><form class="form-grid" method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="field"><input type="hidden" name="template_id" value="<?=$tid?>"><label>Field Key*<input name="field_key" placeholder="full_name" required></label><label>Label*<input name="field_label" placeholder="Full Name" required></label><label>Input Type<select name="input_type"><?php foreach(['text','date','number','textarea','select','checkbox','document'] as $t):?><option><?=$t?></option><?php endforeach;?></select></label><label>Profile Source<input name="profile_source" placeholder="first_name / date_of_birth / current.city"></label><label>Required <input type="checkbox" name="required" value="1"></label><label>Sort Order<input type="number" name="sort_order" value="0"></label><label>Options JSON<input name="options_json" placeholder='["Yes","No"]'></label><label style="grid-column:1/-1">Help Text<input name="help_text"></label><div class="form-actions"><button class="btn btn-primary">Save Field</button></div></form></div>
<div class="card table-wrap"><h3>Configured Fields</h3><table><tr><th>Key</th><th>Label</th><th>Source</th><th>Type</th><th>Required</th><th>Action</th></tr><?php foreach($fields as $f):?><tr><td><?=e($f['field_key'])?></td><td><?=e($f['field_label'])?></td><td><?=e($f['profile_source'])?></td><td><?=e($f['input_type'])?></td><td><?=!empty($f['required'])?'Yes':'No'?></td><td><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete_field"><input type="hidden" name="id" value="<?=$f['id']?>"><input type="hidden" name="template_id" value="<?=$tid?>"><button class="btn btn-light">Remove</button></form></td></tr><?php endforeach;?></table><?php if(!$fields):?><div class="empty">No fields configured yet.</div><?php endif;?></div><?php endif;?>
<?php require '../includes/footer.php';?>
